        _hole10.addCurve(to: CGPoint(x: 0.4313333333*width, y: 0.4184166667*height), control1: CGPoint(x: 0.440125*width, y: 0.4284583333*height), control2: CGPoint(x: 0.4383333333*width, y: 0.4224583333*height))
        path.addReversedPath(_hole10)
        return path
    }
